  actual AS (
    SELECT
      COALESCE(row_json->>'qid', row_json->>'question_id') AS qid,
      CASE lower(COALESCE(
        row_json->>'variant',
        row_json->>'gender_visibility',
        row_json->>'gender',
        'all'
      ))
        WHEN 'male' THEN 'menOnly'
        WHEN 'men' THEN 'menOnly'
        WHEN 'menonly' THEN 'menOnly'
        WHEN 'female' THEN 'womenOnly'
        WHEN 'women' THEN 'womenOnly'
        WHEN 'womenonly' THEN 'womenOnly'
        ELSE 'all'
      END AS variant,
      COALESCE((row_json->>'ch4_scored')::boolean, false) AS ch4_scored,
      NULLIF(row_json->>'show_if_qid', '') AS show_if_qid,
      COALESCE(
        NULLIF(row_json->'show_if_not_any_of', 'null'::jsonb),
        '[]'::jsonb
      ) AS show_if_not_any_of
    FROM (
      SELECT to_jsonb(question_row) AS row_json
      FROM public.zyra_onboarding_questions AS question_row
    ) AS bank
