    UNION ALL
    (SELECT 'missing_in_dart' AS side, actual.* FROM actual
      EXCEPT
     SELECT 'missing_in_dart' AS side, expected.* FROM expected)
  )
  SELECT jsonb_agg(to_jsonb(delta) ORDER BY qid, variant, side)
  INTO v_delta
  FROM delta;

